template <typename T> 
bool hoMatrix<T>::sumOverRow(hoNDArray<T>& res) const
{
    try
    {
        size_t ROW = rows();
        size_t COL = cols();

        if ( res.get_number_of_elements() != ROW )
        {
            res.create(ROW);
        }

        T* pRes = res.begin();

        size_t r, c;

        for ( r=0; r<ROW; r++ )
        {
            pRes[r] = 0;
        }

        for ( c=0; c<COL; c++ )
        {
            for ( r=0; r<ROW; r++ )
            {
                // res(r) += (*this)(r, c);
                pRes[r] += this->data_[r+c*ROW];
            }
        }
    }
    catch (...)
    {
        GERROR_STREAM("Errors in hoMatrix<T>::sumOverRow(hoNDArray<T>& r) ... ");
        return false;
    }

    return true;
}

